    def _change_parameter_on_bts(self, dist_name, param_name, param_value, skip_parameter_relation_errors=True):
        """
        Change parameter on bts by recommissioning

        :param dist_name: Object dist name ie. "MRBTS-1/LNBTS-1/LNMME-0"
        :param param_name: Parameter name ie. "ipAddrPrim"
        :param param_value: Parameter value ie. "10.0.1.99" or [{"eea1":0, "eea0":1, "eea3":8, "eea2":0}]
        :param skip_parameter_relation_errors: Skip parameter relation errors
        :return: Recommissioning status
        """
        return self.connection.perform_parameter_recommissioning(dist_name=dist_name, parameter=param_name,
                                                                 operation='update', value=param_value,
                                                                 skip_parameter_relation_errors=skip_parameter_relation_errors)

    @web_connection_decorator
    def perform_recommissioning(self, delta, skip_parameter_relation_errors=False, should_activate=True, timeout=300):
        """
        Perform parameter recommissioning, update and delete operation can be used.

        :param list delta: list of parameters to update. Sample delta:
                delta = [{
                            'distName': dist_name,
                            'operation': 'update',
                            'parameters': [{
                                            'operation': operation,
                                            'parameterName': parameter,
                                            'value': value}]}]
                where:
                    dist_name: Object dist name ie. "MRBTS-1/LNBTS-1/LNMME-0"
                    parameter: Parameter name ie. "ipAddrPrim"
                    operation: Parameter operation (update or delete)
                    value: Parameter value ie. "10.0.1.99" or [{"eea1":0, "eea0":1, "eea3":8, "eea2":0}]
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :raises taf.sbts.oam.coam.admin.exceptions.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
        """

        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        status = self.connection._api_client.execute_procedure("recommission", parameters, timeout)
        if status is None:
            raise DataNotAvailable("Recommissioning status has not been provided by M-Plane.")
        return status

    @web_connection_decorator
    def reset_fbb(self, fbb_id=0):
        """
        Reset Baseband.

        :param fbb_id: fdd index from 0-2
        :return:reset fbb result
        """
        fbb_info = self.connection.get_fbb_info()
        dist_name = fbb_info[fbb_id]["id"]["internal"]
        return self.connection.reset_unit(dist_name, reset_type="Warm", timeout=300)

    @web_connection_decorator
    def reset_hub(self, hub_id=1):
        """
        Reset ASiR Hub.

        :param hub_id: hud index from 1-12, because in DistName, index start form 1.
        :return:reset hub result

        [History]
        July 1, 2020 - Shi Kun modified the way to get DN of specific HUB ID

        """
        dist_name = None
        hub_info_list = self.connection.get_smallcell_frm()
        for hub_info in hub_info_list:
            expected_last_field = 'ASIRMOD_R-{}'.format(hub_id)
            received_dist_name = hub_info['id']['internal']
            all_fields = received_dist_name.split('/')
            if expected_last_field == all_fields[-1]:
                dist_name = received_dist_name
                break
        if not dist_name:
            raise AssertionError('No dist name found for given hub id: {}'.format(hub_id))
        return self.connection.reset_unit(dist_name, reset_type="Warm", timeout=300)

