    def add_param_to_delta_commissioning_file(self, dist_name, param_name, value):
        """
        Add parameter to delta

        :param dist_name: Object dist name ie. "MRBTS-1/LNBTS-1/LNMME-0"
        :param param_name: Timeout for the operation.
        :param value: str, value of the parameter.
        :return: None
        """
        self.connection.append_parameter_update_to_delta(delta_id=self.delta_store_name,
                                                         dist_name=dist_name,
                                                         parameter=param_name,
                                                         value=value)

    def set_bandwidth_parameters(self, physical_cell_id, value):
        """
        Set bandwidth parameters

        :physical_cell_id: str, cell id of the configured cell.
        :param value: Timeout for the operation.
        :return: None
        """
        dist_name = self.get_dist_name_nrcell(physical_cell_id)
        coreset_index = {'20MHz': '6', '40MHz': '6', '50MHz': '6', '60MHz': '6', '80MHz': '6', '100MHz': '0'}
        self.update_nrcell_parameter(physical_cell_id, 'type0CoresetConfigurationIndex', coreset_index[value])
        self.add_param_to_delta_commissioning_file(dist_name, 'chBw', value)

    def get_nrcell_id_for_physical_id(self, physical_cell_id):

        """
        Get Cell Id for the physical Cell Id.
        :return: nrcell id for phusical id
        """
        cells_info = self.connection.get_managed_objects('NRCELL_A', 10)
        for cell_index, cell_info in enumerate(cells_info, 1):
            if str(cell_info["parameters"]['physCellId']) == str(physical_cell_id):
                return cell_info['distName'].split('/')[-1].replace("_A", "")

        raise AssertionError("No Cell Found for given physical cell id: %s" % (physical_cell_id,))

    def update_nrcell_parameter(self, physical_cell_id, param_name, value):
        """
        Update the Cell Parameter by using delta commissioning.

        :param physical_cell_id: str, cell id of the configured cell.
        :param param_name: str, name of the parameter.
        :param value: str, value of the parameter.
        :recommission: bool, value to see if recommission will be done.
        :return:   None
        """
        dist_name = self.get_dist_name_nrcell(physical_cell_id)
        self.add_param_to_delta_commissioning_file(dist_name, param_name, value)
        return

    def get_dist_name_nrcell(self, physical_cell_id):
        """
        Get the dist_name of the NRCell.

        :param physical_cell_id: str, cell id of the cell.
        :return: dist name for nrcell
        """
        nr_cell_id = self.get_nrcell_id_for_physical_id(physical_cell_id)
        return "/".join(["MRBTS-" + str(self.mrbts_id), "NRBTS-" + str(self.nrbts_id), nr_cell_id])

    @web_connection_decorator
    def configure_bandwidth(self, physical_cell_id, value):
        """
        Set bandwidth configuration.

        :param physical_cell_id: str, cell id of the cell.
        :value:  new bandwidth value
        :return:   None
        """
        if not self.is_bandwidth_configure(value):
            self.set_bandwidth_parameters(physical_cell_id, value)

    def is_bandwidth_configure(self, value):
        """
        Check bandwidth configuration whether the configuration already exists.

        :value:  value
        :return:   True or False
        """
        bw_info = self.connection.get_managed_objects('NRCELL_A', 10)
        if not bw_info:
            return False
        for cell_bw_info in bw_info:
            if not str(cell_bw_info["parameters"]['chBw']).lower() == str(value).lower():
                return False
        return True

    def collect_delta_store(self):
        """
        Collect delta store.
        :return: delta store
        """
        return self.connection.get_delta(delta_id=self.delta_store_name)

    @web_connection_decorator
    def recommission_with_delta(self, should_activate=True):
        """
        Perform delta recommissioning with activation.
        :should_activate: True or False
        :return: None
        """
        delta_json = self.collect_delta_store()
        if delta_json == '[]':
            raise AssertionError('No new parameter added to perform delta commisioning')
        self.connection.perform_delta_recommissioning(delta_file=delta_json,
                                                      skip_parameter_relation_errors=True,
                                                      should_activate=should_activate)

    @web_connection_decorator
    def initialise_delta_store(self, name):
        """
        Initialize delta commissioning.
        :name: Delta name
        :return: None
        """
        self.delta_store_name = name
        self.delete_delta_if_already_present()
        self.delta_store = self.connection.create_delta(delta_id=self.delta_store_name)

    def delete_delta_if_already_present(self, ):
        """
        Remove delta if already exists.
        :return: None
        """
        try:
            self.connection.remove_all_delta_id()
        except KeyError:
            pass

    @web_connection_decorator
    def delete_cell(self, cell_id=2):
        cell_id = int(cell_id)
        delta = [{
            'distName': "MRBTS-{}/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-{}".format(self.mrbts_id, cell_id),
            'operation': 'delete',
            'parameters': []
        }, {
            'distName': "MRBTS-{}/NRBTS-{}/NRCELL-{}".format(self.mrbts_id, self.nrbts_id, cell_id),
            'operation': 'delete',
            'parameters': []
        }]

        self.perform_recommissioning(delta=delta, skip_parameter_relation_errors=True)

    @web_connection_decorator
    def get_param_value(self, object, param):
        """
        Get Parameter value.
        :param object: eg. 'SMOD', 'ASIRMOD_R'...
        :param param: parameter name
        :return: parameter value
        """
        managed_objects = self.connection.get_managed_objects(object, 10)
        dist_name = managed_objects[0]['distName']
        param_value = self.connection.get_parameters(dist_name, param)
        return str(param_value[param])

